// n8n Code node "Verify signature" (mode: Run Once for All Items).
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto and LENDLOOP_WEBHOOK_SECRET in the n8n environment.
// Never log the payload, headers or secret.
const crypto = require('crypto');

const item = $input.first();
const headers = {};
for (const [k, v] of Object.entries(item.json.headers || {})) headers[k.toLowerCase()] = v;

const reject = () => [{ json: { valid: false, duplicate: false } }];

const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) return reject();

const ts = String(headers['x-lendloop-timestamp'] || '');
const sigHeader = String(headers['x-lendloop-signature'] || '');
if (!/^\d{1,12}$/.test(ts)) return reject();
const sigMatch = /^sha256=([0-9a-fA-F]{64})$/.exec(sigHeader);
if (!sigMatch) return reject();

// Replay window: +-300 s (ADR-021).
if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) return reject();

// Raw body: webhook option "Raw Body" exposes the exact bytes as binary property `data`.
let raw;
try {
  raw = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  return reject();
}

const expected = crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest();
const given = Buffer.from(sigMatch[1], 'hex');
// Equal lengths are guaranteed (32 bytes each), so timingSafeEqual cannot throw.
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) return reject();

let payload;
try {
  payload = JSON.parse(raw.toString('utf8'));
} catch (e) {
  return reject();
}
const s = (v) => typeof v === 'string';
if (
  !payload ||
  !s(payload.eventId) ||
  !s(payload.eventType) ||
  !s(payload.toolName) ||
  !payload.recipient ||
  !s(payload.recipient.email)
) {
  return reject();
}

// De-duplication (ADR-026): only events that were already EMAILED are recorded (see "Record event").
const staticData = $getWorkflowStaticData('global');
const seen = staticData.processedEvents || {};
const duplicate = Object.prototype.hasOwnProperty.call(seen, payload.eventId);

return [{ json: { valid: true, duplicate, payload } }];

// n8n Code node "Compose email": builds subject/text/html from the verified payload.
// Every interpolated value is HTML-escaped in the html body; the subject/text are plain text.
const p = $input.first().json.payload;

const esc = (v) =>
  String(v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
// Header-injection guard for the subject (CR/LF/control chars out, length cap).
const line = (v) => String(v).replace(/[\u0000-\u001F\u007F-\u009F]/g, ' ').trim().slice(0, 120);

const tool = line(p.toolName);
const name = line(p.recipient.name || 'there');
const range = `${p.startDate} to ${p.endDate}`;

const templates = {
  request_created: {
    subject: `New borrow request for ${tool}`,
    body: `Someone asked to borrow "${tool}" from ${range}. Open LendLoop to approve or decline the request.`,
  },
  request_approved: {
    subject: `Your request for ${tool} was approved`,
    body: `Good news: your request to borrow "${tool}" (${range}) was approved. Please arrange the hand-over with the owner.`,
  },
  request_declined: {
    subject: `Your request for ${tool} was declined`,
    body: `Your request to borrow "${tool}" (${range}) was declined. You can browse other tools on LendLoop.`,
  },
  request_cancelled: {
    subject: `Request for ${tool} was cancelled`,
    body: `The request to borrow "${tool}" (${range}) was cancelled.`,
  },
  loan_returned: {
    subject: `${tool} was marked as returned`,
    body: `"${tool}" (${range}) was marked as returned. Thanks for lending and borrowing responsibly!`,
  },
};
const tpl = templates[p.eventType];
if (!tpl) {
  // Unknown type: fail loudly (error workflow + 5xx) rather than silently dropping the event.
  throw new Error('Unsupported eventType');
}

const text = `Hi ${name},\n\n${tpl.body}\n\n-- LendLoop`;
const html =
  `<p>Hi ${esc(name)},</p>` +
  `<p>${esc(tpl.body)}</p>` +
  `<p style="color:#666">LendLoop &middot; Borrow what you need. Lend what you don't.</p>`;

return [
  {
    json: {
      eventId: p.eventId,
      to: p.recipient.email,
      subject: tpl.subject,
      text,
      html,
    },
  },
];

// n8n Code node "Record event": remember an eventId AFTER its email was sent, so Convex retries of
// a failed delivery are not mistaken for duplicates. Keeps the newest 500 ids. Runs only on success.
const eventId = $('Compose email').first().json.eventId;
const staticData = $getWorkflowStaticData('global');
const seen = staticData.processedEvents || {};
seen[eventId] = Date.now();
const ids = Object.keys(seen);
if (ids.length > 500) {
  ids.sort((a, b) => seen[a] - seen[b]);
  for (const id of ids.slice(0, ids.length - 500)) delete seen[id];
}
staticData.processedEvents = seen;
return [{ json: { recorded: true } }];
